const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Acre, Brazil geometry
  const acre = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Acre'))
    .geometry();

  // 2. Define time periods
  const julyStart = '2005-07-20';
  const julyEnd = '2005-07-31';
  const septStart = '2005-09-20';
  const septEnd = '2005-09-30';

  // 3. Load MODIS Burned Area product
  const julyCol = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterBounds(acre)
    .filterDate(julyStart, julyEnd);

  const septCol = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterBounds(acre)
    .filterDate(septStart, septEnd);

  const julySize = julyCol.size().getInfo();
  const septSize = septCol.size().getInfo();

  console.log(`July images: ${julySize}, Sept images: ${septSize}`);

  // 4. Check for empty collections
  if (julySize === 0 || septSize === 0) {
    console.log('Empty collection for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Process burned area (BurnDate band > 0 indicates burned)
  const julyImg = julyCol.first();
  const septImg = septCol.first();

  // BurnDate band: day of year when burned (1-366), 0 = not burned
  const julyBurned = julyImg.select('BurnDate').gt(0);
  const septBurned = septImg.select('BurnDate').gt(0);

  // 6. Calculate burned area extent (count of burned pixels)
  const julyStats = julyBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: acre,
    scale: 500,
    maxPixels: 1e9
  });

  const septStats = septBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: acre,
    scale: 500,
    maxPixels: 1e9
  });

  const julyCount = julyStats.get('BurnDate').getInfo();
  const septCount = septStats.get('BurnDate').getInfo();

  // 7. Also get total pixel counts to check for C2
  const julyTotal = julyImg.select('BurnDate').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: acre,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  const septTotal = septImg.select('BurnDate').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: acre,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  console.log(`July: ${julyCount} burned pixels out of ${julyTotal} total`);
  console.log(`Sept: ${septCount} burned pixels out of ${septTotal} total`);

  // 8. Validation
  if (julyTotal === 0 || septTotal === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (julyCount === null || septCount === null || 
      typeof julyCount === 'undefined' || typeof septCount === 'undefined') {
    console.log('Calculation failed - null/undefined result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Calculate burned area in km²
  const pixelArea = 500 * 500 / 1e6; // 0.25 km²
  const julyArea = julyCount * pixelArea;
  const septArea = septCount * pixelArea;

  console.log(`July burned area: ${julyArea.toFixed(2)} km²`);
  console.log(`Sept burned area: ${septArea.toFixed(2)} km²`);

  // 10. Final answer
  if (septArea > julyArea) {
    console.log('Burned area increased from July to September.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Burned area did not increase from July to September.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
